-- editorial_lesson_titles_2026-07-31.sql
--
-- Rewrites 578 student-facing lesson titles that were still raw YouTube
-- keyword soup, into honest editorial titles. Audit finding, 31 July 2026.
--
-- WHY THESE WERE MISSED: the 29 July editorial pass rewrote 1703 titles, and the
-- Competishun+ / Mohit Tyagi batches imported on 30-31 July landed AFTER it, so
-- they never went through it. Measured with the repo's own rules
-- (src/titleQuality.js) against live production: 576 of 3088 lesson titles
-- (18.7%) violated them -- 351 pipe-separated keyword lists, 152 over the
-- 90-character limit, 252 with collapsed-whitespace damage, plus promotional
-- phrases and ALL-CAPS.
--
-- HOW THESE WERE WRITTEN: a 15-agent editorial pass (10 drafters working
-- course-by-course with full lesson context, then 5 adversarial reviewers) under
-- one overriding rule -- NOTHING IS INVENTED. A title may only use information
-- already in that lesson's own raw title, its chapter, and its position. Where
-- the source distinguishes lessons only by a number, the result is
-- "<Chapter> — Lecture N" rather than a guessed topic: a title promising a topic
-- the video does not cover would be worse than the keyword soup it replaced.
--
-- INDEPENDENTLY VALIDATED before generating this file, not taken on trust:
--   * 576/576 coverage of the violating set, no duplicate ids;
--   * every "before" byte-matches the live database (so this file cannot
--     silently overwrite a title someone changed in the meantime);
--   * every "after" passes titleQuality with zero issues;
--   * no title left unchanged;
--   * a fabrication sweep flagged 165 titles containing a word absent from the
--     original; all but 7 were morphological variants, and all 7 remaining were
--     correct domain expansions confirmed against the video's own chapter --
--     "N and O" -> Nitrogen/Oxygen (chapter: Groups 15 and 16), "GOC" ->
--     General Organic Chemistry, "ORM" -> Organic Reaction Mechanisms. Zero
--     actual fabrication.
--
-- ALSO FIXES 2 PRE-EXISTING DUPLICATES (course 282): Aakash published two
-- different videos (ids 2822/2823, 23 and 50 minutes long) under a byte-identical
-- title, so the lesson list showed two indistinguishable rows. Disambiguated by
-- their real position in the course, since nothing else about them is knowable
-- without watching.
--
-- REVERSIBLE: videos.source_title holds the original YouTube title. This file
-- BACKFILLS source_title from the current title wherever it is NULL *before*
-- overwriting, so the revert path stays complete:
--     update public.videos set title = source_title where source_title is not null;
--
-- Idempotent: each row applies only if the title still matches its recorded
-- "before" (or is already the "after"), and raises rather than guessing otherwise.

begin;

create temp table _title_rewrite (video_id bigint primary key, before_title text, after_title text) on commit drop;


-- 1. Preserve the revert path FIRST. 578 rows are being rewritten and many
--    have never been edited, so their current title IS the raw YouTube original.
update public.videos v
   set source_title = v.title
  from _title_rewrite t
 where v.id = t.video_id
   and v.source_title is null;

-- 2. Apply, refusing to overwrite anything that has drifted.
do $apply$
declare
  r record;
  v_current text;
  v_applied int := 0;
  v_skipped int := 0;
begin
  for r in select * from _title_rewrite loop
    select title into v_current from public.videos where id = r.video_id;
    if v_current is null then
      raise exception 'video % not found', r.video_id;
    elsif v_current = r.after_title then
      v_skipped := v_skipped + 1;           -- already applied (safe re-run)
    elsif v_current is distinct from r.before_title then
      raise exception
        'video % no longer has the expected title. expected %, found % -- someone edited it, refusing to overwrite',
        r.video_id, r.before_title, v_current;
    else
      update public.videos
         set title = r.after_title, title_review_status = 'approved', updated_at = now()
       where id = r.video_id;
      v_applied := v_applied + 1;
    end if;
  end loop;
  raise notice 'applied % title(s), % already current', v_applied, v_skipped;
end
$apply$;

-- ---------------------------------------------------------------------
-- SELF-VERIFICATION
-- ---------------------------------------------------------------------
do $verify$
declare
  v_wrong int;
  v_norevert int;
  v_dupes int;
begin
  select count(*) into v_wrong
    from public.videos v join _title_rewrite t on t.video_id = v.id
   where v.title is distinct from t.after_title;
  if v_wrong <> 0 then
    raise exception '% title(s) did not end up as intended', v_wrong;
  end if;

  select count(*) into v_norevert
    from public.videos v join _title_rewrite t on t.video_id = v.id
   where v.source_title is null;
  if v_norevert <> 0 then
    raise exception '% rewritten row(s) have no source_title, so they cannot be reverted', v_norevert;
  end if;

  -- No course may contain two lessons rendering as the same string.
  select count(*) into v_dupes from (
    select pv.playlist_id, v.title
      from public.playlist_videos pv
      join public.videos v on v.id = pv.video_id
     group by pv.playlist_id, v.title
    having count(*) > 1
  ) d;
  if v_dupes <> 0 then
    raise exception '% course/title pair(s) are duplicated within a course', v_dupes;
  end if;

  raise notice 'SELF-TEST PASSED: 578 titles rewritten, every one revertible via source_title, no duplicate lesson titles within any course.';
end
$verify$;

commit;
